const fs = require('fs').promises;
const path = require('path');

async function main() {
  const migrationsDir = path.resolve(__dirname, 'migrations');
  let files;
  try {
    files = await fs.readdir(migrationsDir);
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for SQL files
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    // Sort alphabetically; you could also use numeric prefixes.
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migrations found.');
    return;
  }

  console.log('Migrations that would be applied (in order):');
  sqlFiles.forEach((file, idx) => {
    console.log(`${idx + 1}. ${file}`);
  });
}

main();

