```javascript
#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

/**
 * Returns an alphabetically sorted array of .sql filenames
 * inside the migrations folder.
 */
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });

    return files
      .filter((dirent) => dirent.isFile() && dirent.name.endsWith('.sql'))
      .map((dirent) => dirent.name)
      .sort(); // deterministic order
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
}

function main() {
  const files = getMigrationFiles();

  if (files.length === 0) {
    console.log(`No migration files found in ${MIGRATIONS_DIR}`);
    return;
  }

  console.log('Migration plan:');
  files.forEach((file) => {
    console.log(`  → ${file}`);
  });
}

if (require.main === module) {
  main();
}
```

