#!/usr/bin/env node

/*
 * Simple migration preview script
 *
 * This script looks into the ./migrations directory, gathers all *.sql files,
 * sorts them in the natural order (e.g. 001_create_users.sql, 002_add_idx.sql),
 * and logs the filename/path it would apply when running the migrations.
 *
 * It does NOT execute the SQL against a database; it only reports the order.
 * This can be used before running a full migration to double‑check the order.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.warn(`Directory ${dir} does not exist.`);
    return [];
  }
  const files = fs.readdirSync(dir);
  // Filter for .sql files and ignore other content
  return files.filter((f) => f.endsWith('.sql'));
}

function naturalSort(a, b) {
  // Quick natural sort: split on non-digit chars
  const split = (s) => s.split(/(\d+)/).map((x) => (x ? (isNaN(x) ? x : Number(x)) : ''));
  const aParts = split(a);
  const bParts = split(b);
  for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
    const aPart = aParts[i];
    const bPart = bParts[i];
    if (aPart === undefined) return -1;
    if (bPart === undefined) return 1;
    if (aPart < bPart) return -1;
    if (aPart > bPart) return 1;
  }
  return 0;
}

function main() {
  const sqlFiles = getSqlFiles(MIGRATIONS_DIR).sort(naturalSort);
  if (sqlFiles.length === 0) {
    console.log('No .sql migration files found in', MIGRATIONS_DIR);
    return;
  }
  console.log('Migration files to be applied (in order):');
  sqlFiles.forEach((file) => {
    console.log('- ', path.join('migrations', file));
  });
}

if (require.main === module) {
  main();
} else {
  module.exports = { main, MIGRATIONS_DIR, getSqlFiles, naturalSort };
}

