  }
}

/**
 * Read & return an array of .sql migration files sorted
 * lexicographically from the migrations directory.
 */
function readMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });
    const sqlFiles = files
      .filter((dirent) => dirent.isFile() && dirent.name.endsWith('.sql'))
      .map((dirent) => dirent.name);
    sqlFiles.sort(); // Ascending order
    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }
}

