#!/usr/bin/env node

/**
 * A simple migration runner that lists SQL migration files in
 * the `./migrations` directory and logs each one in the order
 * they would be applied.
 */

const fs = require('fs');
const path = require('path');

// Resolve the absolute path to the migrations directory.
const migrationsDir = path.resolve(__dirname, 'migrations');

// Helper that returns a promise that resolves to the list of migration files.
function getMigrationFiles(dir) {
  return new Promise((resolve, reject) => {
    fs.readdir(dir, { withFileTypes: true }, (err, entries) => {
      if (err) {
        return reject(err);
      }

      // Filter for regular files ending in .sql.
      const files = entries
        .filter((e) => e.isFile() && e.name.endsWith('.sql'))
        .map((e) => e.name)
        .sort(); // Alphabetical sort – good for numeric prefixes.

      resolve(files);
    });
  });
}

async function run() {
  try {
    const files = await getMigrationFiles(migrationsDir);
    if (files.length === 0) {
      console.log('No migration files found in ./migrations.');
      return;
    }
    console.log('Migration files that would be applied (in order):');
    files.forEach((file) => console.log('  - ' + file));
  } catch (err) {
    console.error('Error reading migrations:', err);
    process.exit(1);
  }
}

run();

